// scroll-gallery.js
// Justified row layout per date section + MutationObserver for infinite scroll.
// Preserves overlay UI state, waits for newly appended section images before layout,
// ensures images receive pointer events so overlay.js handlers run, dispatches a
// lightweight 'justified:resized' event per item, and enforces selection-mode interactivity
// so only select controls (and image clicks handled by overlay.js) remain active while items are selected.
//
// This file is the v2 variant — updated so select controls and ALL their descendants remain interactive
// while selection-mode is active (fixes clicks inside the select button markup).
//
// Public API: window.ScrollJustifiedGallery.{ layoutAll, layoutSection, setContentAppendedCallback, disconnectObserver, reconnectObserver }
// Include this file after the HTML for #scroll-gallery / #infinite-scroll-gallery (or use defer).

(function () {
    function init() {
        let container = document.getElementById('scroll-gallery');
        if (!container) {
            container = document.getElementById('infinite-scroll-gallery');
            if (!container) {
                console.warn('scroll-gallery: #scroll-gallery container not found.');
                return;
            }
        }

        const config = {
            targetRowHeight:
                parseInt(getComputedStyle(document.documentElement).getPropertyValue('--jg-target-row-height')) || 225,
            gap: parseInt(getComputedStyle(document.documentElement).getPropertyValue('--jg-gap')) || 6,
            justifyLastRow: false,
            resizeDebounce: 120,
            mutationDebounce: 120
        };

        function debounce(fn, wait) {
            let t;
            return function (...args) {
                clearTimeout(t);
                t = setTimeout(() => fn.apply(this, args), wait);
            };
        }

        function itemAspectRatio(itemEl) {
            const img = itemEl.querySelector('img');
            if (!img) return 1;
            if (img.dataset && img.dataset.aspect) return Number(img.dataset.aspect) || 1;
            if (img.hasAttribute('width') && img.hasAttribute('height')) {
                const w = Number(img.getAttribute('width')), h = Number(img.getAttribute('height'));
                if (w > 0 && h > 0) return w / h;
            }
            if (img.naturalWidth && img.naturalHeight) return img.naturalWidth / img.naturalHeight;
            return 1;
        }

        function availableContentWidth(el) {
            const computed = getComputedStyle(el);
            const padLeft = parseFloat(computed.paddingLeft) || 0;
            const padRight = parseFloat(computed.paddingRight) || 0;
            return Math.max(1, el.clientWidth - padLeft - padRight);
        }

        async function waitForSectionImages(sectionEl) {
            const imgs = Array.from(sectionEl.querySelectorAll('img'));
            if (!imgs.length) return;
            await Promise.all(imgs.map(img => {
                if (img.decode) return img.decode().catch(() => Promise.resolve());
                if (img.complete && img.naturalWidth) return Promise.resolve();
                return new Promise(res => { img.onload = img.onerror = res; });
            }));
        }

        function getMetadataIdFromItem(el) {
            const link = el.querySelector('.mediaLink');
            if (link) {
                const dataId = link.getAttribute('data-metadata-id') || (link.dataset && link.dataset.metadataId);
                if (dataId) return dataId;
            }
            if (el.id && el.id.indexOf('photoThumbnailContainer') === 0) {
                return el.id.replace('photoThumbnailContainer', '');
            }
            return null;
        }

        function captureOverlayState(metadataId, itemEl) {
            try {
                const state = {};
                const img = itemEl.querySelector('img.photo-thumbnail-image');
                state.imageOpacity = img ? ((img.style && img.style.opacity) ? img.style.opacity : getComputedStyle(img).opacity) : null;

                const overlayIds = ['tntl', 'tncentered', 'tnbr', 'tnbl', 'tntr'];
                state.overlays = {};
                overlayIds.forEach(prefix => {
                    const node = document.getElementById(prefix + metadataId);
                    if (node) {
                        state.overlays[prefix] = (node.style && node.style.display) ? node.style.display : getComputedStyle(node).display;
                        state.overlays[prefix + '_pe'] = (node.style && node.style.pointerEvents) ? node.style.pointerEvents : null;
                    } else {
                        state.overlays[prefix] = null;
                        state.overlays[prefix + '_pe'] = null;
                    }
                });
                return state;
            } catch (e) {
                return null;
            }
        }

        function restoreOverlayState(metadataId, itemEl, state) {
            try {
                if (!state) return;
                if (state.imageOpacity !== null && state.imageOpacity !== undefined) {
                    const img = itemEl.querySelector('img.photo-thumbnail-image');
                    if (img) img.style.opacity = state.imageOpacity;
                }
                const overlayIds = ['tntl', 'tncentered', 'tnbr', 'tnbl', 'tntr'];
                overlayIds.forEach(prefix => {
                    const val = state.overlays && state.overlays[prefix];
                    const node = document.getElementById(prefix + metadataId);
                    if (node && (val !== null && val !== undefined)) {
                        node.style.display = val;
                    }
                    const pe = state.overlays && state.overlays[prefix + '_pe'];
                    if (node && pe) node.style.pointerEvents = pe;
                });
            } catch (e) {
                // ignore
            }
        }

        function dispatchResizedEventForItem(itemEl, metadataId) {
            try {
                const ev = new CustomEvent('justified:resized', { detail: { metadataId } });
                itemEl.dispatchEvent(ev);
                document.dispatchEvent(ev);
            } catch (e) {
                // ignore
            }
        }

        // Selection-mode: make links/buttons inert while selection is active; allow select controls and images.
        // Ensure select controls and all their descendant nodes remain interactive.
        let clickCaptureHandler = null;
        function clickCapture(event) {
            try {
                if (!document.querySelector('.bi-circle-fill')) return;
                const tgt = event.target;
                const containerEl = tgt && tgt.closest && tgt.closest('.photo-thumbnail-container');
                if (!containerEl) return;

                // Allowed targets: image or inside a select control
                const isImage = tgt.matches && tgt.matches('img.photo-thumbnail-image');
                const selectAncestor = tgt.closest && (tgt.closest('[id^="select"]') || tgt.closest('.select'));
                if (isImage || selectAncestor) {
                    return; // allow
                }

                // Block all other clicks inside thumbnails while selection mode active
                event.stopImmediatePropagation();
                event.stopPropagation();
                event.preventDefault();
            } catch (e) {
                // swallow
            }
        }

        function applySelectionInteractivity(enable) {
            try {
                const scope = container || document;
                const disableSelectors = [
                    '.photo-thumbnail-container .mediaLink',
                    '.photo-thumbnail-container a',
                    '.photo-thumbnail-container button',
                    '.photo-thumbnail-container input',
                    '.photo-thumbnail-container select',
                    '.photo-thumbnail-container textarea',
                    '.photo-thumbnail-container [role="button"]'
                ];
                let interactiveEls = [];
                disableSelectors.forEach(sel => {
                    Array.from(scope.querySelectorAll(sel)).forEach(e => interactiveEls.push(e));
                });

                const allowSelectors = [
                    '[id^="select"]',
                    '.select'
                ];
                const allowed = new Set();
                allowSelectors.forEach(sel => {
                    Array.from(scope.querySelectorAll(sel)).forEach(el => {
                        allowed.add(el);
                        // Add descendants so clicks on inner nodes are allowed
                        try { Array.from(el.querySelectorAll('*')).forEach(ch => allowed.add(ch)); } catch (e) {}
                    });
                });
                // images are allowed
                Array.from(scope.querySelectorAll('.photo-thumbnail-container img.photo-thumbnail-image')).forEach(e => allowed.add(e));

                if (enable) {
                    interactiveEls.forEach(el => { if (!allowed.has(el)) el.style.pointerEvents = 'none'; });
                    allowed.forEach(a => { try { a.style.pointerEvents = 'auto'; } catch (e) {} });
                    document.documentElement.classList.add('jg-selection-active');

                    if (!clickCaptureHandler) {
                        clickCaptureHandler = clickCapture;
                        document.addEventListener('click', clickCaptureHandler, true);
                    }
                } else {
                    interactiveEls.forEach(el => { el.style.pointerEvents = ''; });
                    allowed.forEach(a => { try { a.style.pointerEvents = ''; } catch (e) {} });
                    document.documentElement.classList.remove('jg-selection-active');

                    if (clickCaptureHandler) {
                        document.removeEventListener('click', clickCaptureHandler, true);
                        clickCaptureHandler = null;
                    }
                }
            } catch (e) {
                console.error('applySelectionInteractivity error', e);
            }
        }

        function isSelectionActive() {
            return document.querySelector('.bi-circle-fill') !== null;
        }

        const selectionObserver = new MutationObserver(debounce(function () {
            const active = isSelectionActive();
            applySelectionInteractivity(active);
        }, 80));

        function observeSelectionChanges() {
            try {
                if (document.body) {
                    selectionObserver.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'style'] });
                    applySelectionInteractivity(isSelectionActive());
                }
            } catch (e) {
                // ignore
            }
        }

        function layoutDateBody(dateBodyEl) {
            if (!dateBodyEl) return;
            const gap = config.gap;
            const containerWidth = availableContentWidth(dateBodyEl);
            const itemEls = Array.from(dateBodyEl.querySelectorAll('.photo-thumbnail-container'));
            if (!itemEls.length) return;

            const captured = new Map();
            const items = itemEls.map(el => {
                const metadataId = getMetadataIdFromItem(el);
                const state = metadataId ? captureOverlayState(metadataId, el) : null;
                if (metadataId && state) captured.set(metadataId, state);
                return { el, aspect: itemAspectRatio(el) || 1, metadataId };
            });

            items.forEach(it => {
                it.el.style.width = '';
                it.el.style.height = '';
                it.el.style.marginRight = '';
                it.el.style.marginBottom = '';
            });

            const rows = [];
            let row = [];
            let rowAspectSum = 0;
            const targetH = config.targetRowHeight;

            items.forEach((it, idx) => {
                row.push(it);
                rowAspectSum += it.aspect;
                const rowWAtTarget = rowAspectSum * targetH + (row.length - 1) * gap;
                if (rowWAtTarget >= containerWidth) {
                    rows.push({ items: row.slice(), aspectSum: rowAspectSum, isLast: false });
                    row = []; rowAspectSum = 0;
                } else if (idx === items.length - 1) {
                    rows.push({ items: row.slice(), aspectSum: rowAspectSum, isLast: true });
                    row = []; rowAspectSum = 0;
                }
            });

            rows.forEach(r => {
                const isLast = r.isLast;
                if (isLast && !config.justifyLastRow) {
                    const height = targetH;
                    r.items.forEach((it, i) => {
                        const w = Math.round(it.aspect * height);
                        it.el.style.width = w + 'px';
                        it.el.style.height = Math.round(height) + 'px';
                        it.el.style.marginRight = (i < r.items.length - 1) ? gap + 'px' : '0px';
                        it.el.style.marginBottom = gap + 'px';
                        const img = it.el.querySelector('img.photo-thumbnail-image');
                        if (img) { img.style.pointerEvents = 'auto'; img.style.zIndex = '0'; }
                        if (it.metadataId && captured.has(it.metadataId)) restoreOverlayState(it.metadataId, it.el, captured.get(it.metadataId));
                        if (it.metadataId) dispatchResizedEventForItem(it.el, it.metadataId);
                    });
                } else {
                    const totalGap = (r.items.length - 1) * gap;
                    const height = (containerWidth - totalGap) / r.aspectSum;
                    let usedWidth = 0;
                    r.items.forEach((it, i) => {
                        const w = Math.round(it.aspect * height);
                        usedWidth += w;
                        it.el.style.width = w + 'px';
                        it.el.style.height = Math.round(height) + 'px';
                        it.el.style.marginRight = (i < r.items.length - 1) ? gap + 'px' : '0px';
                        it.el.style.marginBottom = gap + 'px';
                        const img = it.el.querySelector('img.photo-thumbnail-image');
                        if (img) { img.style.pointerEvents = 'auto'; img.style.zIndex = '0'; }
                        if (it.metadataId && captured.has(it.metadataId)) restoreOverlayState(it.metadataId, it.el, captured.get(it.metadataId));
                        if (it.metadataId) dispatchResizedEventForItem(it.el, it.metadataId);
                    });
                    const discrepancy = containerWidth - totalGap - usedWidth;
                    if (discrepancy !== 0 && r.items.length) {
                        const lastItem = r.items[r.items.length - 1];
                        const last = lastItem.el;
                        last.style.width = (parseInt(last.style.width, 10) + discrepancy) + 'px';
                        const lastImg = last.querySelector('img.photo-thumbnail-image');
                        if (lastImg) { lastImg.style.pointerEvents = 'auto'; lastImg.style.zIndex = '0'; }
                        if (lastItem.metadataId && captured.has(lastItem.metadataId)) restoreOverlayState(lastItem.metadataId, last, captured.get(lastItem.metadataId));
                        if (lastItem.metadataId) dispatchResizedEventForItem(last, lastItem.metadataId);
                    }
                }
            });
        }

        function layoutAllSections() {
            const dateBodies = container.querySelectorAll('.dateSection .row');
            dateBodies.forEach(db => layoutDateBody(db));
        }
        const debouncedLayoutAll = debounce(layoutAllSections, config.resizeDebounce);
        window.addEventListener('resize', debouncedLayoutAll);

        const resizeObserver = new ResizeObserver(debouncedLayoutAll);
        resizeObserver.observe(container);

        function layoutDateSection(sectionEl) {
            if (!sectionEl) return;
            const dateBody = sectionEl.querySelector('.row');
            layoutDateBody(dateBody);
        }

        let contentAppendedCallback = null;
        function setContentAppendedCallback(cb) { contentAppendedCallback = typeof cb === 'function' ? cb : null; }

        const onMutations = debounce(function (mutations) {
            const addedSections = new Set();
            let newContentDetected = false;

            for (const m of mutations) {
                if (m.type === 'childList') {
                    m.addedNodes.forEach(node => {
                        if (!(node instanceof Element)) return;
                        if (node.classList && node.classList.contains('dateSection')) { addedSections.add(node); newContentDetected = true; }
                        else node.querySelectorAll && node.querySelectorAll('.dateSection').forEach(s => { addedSections.add(s); newContentDetected = true; });
                    });

                    m.addedNodes.forEach(node => {
                        if (!(node instanceof Element)) return;
                        if (node.matches && node.matches('.photo-thumbnail-container')) {
                            const parentSection = node.closest('.dateSection');
                            if (parentSection) { addedSections.add(parentSection); newContentDetected = true; }
                        } else {
                            node.querySelectorAll && node.querySelectorAll('.photo-thumbnail-container').forEach(n => {
                                const parentSection = n.closest('.dateSection');
                                if (parentSection) { addedSections.add(parentSection); newContentDetected = true; }
                            });
                        }
                    });
                }
            }

            if (addedSections.size > 0) {
                addedSections.forEach(sec => {
                    waitForSectionImages(sec).then(() => { layoutDateSection(sec); }).catch(() => { layoutDateSection(sec); });
                });
            } else {
                layoutAllSections();
            }

            if (newContentDetected && contentAppendedCallback) {
                try { contentAppendedCallback(); } catch (e) { console.error('contentAppendedCallback error', e); }
            }
        }, config.mutationDebounce);

        const mo = new MutationObserver(onMutations);
        mo.observe(container, { childList: true, subtree: true });

        function disconnectObserver() { mo.disconnect(); }
        function reconnectObserver() { mo.observe(container, { childList: true, subtree: true }); }

        // Start selection observer
        observeSelectionChanges();

        window.ScrollJustifiedGallery = {
            layoutAll: layoutAllSections,
            layoutSection: layoutDateSection,
            setContentAppendedCallback: setContentAppendedCallback,
            disconnectObserver: disconnectObserver,
            reconnectObserver: reconnectObserver
        };

        // Initial layout (wait for images decode to reduce flashes)
        setTimeout(() => {
            const sections = Array.from(container.querySelectorAll('.dateSection .row'));
            if (sections.length === 0) { layoutAllSections(); return; }
            Promise.all(sections.map(s => waitForSectionImages(s))).then(() => { layoutAllSections(); }).catch(() => { layoutAllSections(); });
        }, 20);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();